    {
        $sql = "
            CREATE OR REPLACE FUNCTION clonar_layout(codigo NUMERIC, descricao VARCHAR, ano INTEGER, novo_codigo INTEGER DEFAULT 0)
              RETURNS NUMERIC AS $$
            DECLARE
              layouts         RECORD;
              linhas          RECORD;
              campos          RECORD;
              perguntas       RECORD;
              codigo_layout   NUMERIC;
              codigo_linha    NUMERIC;
              codigo_campo    NUMERIC;
              codigo_pergunta NUMERIC;
            BEGIN
              PERFORM setval('db_layouttxt_db50_codigo_seq', (SELECT max(db50_codigo)
                                                              FROM db_layouttxt));
            
              PERFORM setval('db_layoutlinha_db51_codigo_seq', (SELECT max(db51_codigo)
                                                                FROM db_layoutlinha));
            
              PERFORM setval('db_layoutcampos_db52_codigo_seq', (SELECT max(db52_codigo)
                                                                 FROM db_layoutcampos));
            
              FOR layouts IN
            
              SELECT *
              FROM db_layouttxt
              WHERE db50_codigo IN (codigo)
            
              LOOP
            
                IF novo_codigo = 0
                THEN
                    SELECT nextval('db_layouttxt_db50_codigo_seq')
                    INTO codigo_layout;
                ELSE
                    codigo_layout := novo_codigo;
                END IF;
            
                INSERT INTO db_layouttxt (
                  db50_codigo,
                  db50_descr,
                  db50_quantlinhas,
                  db50_obs,
                  db50_layouttxtgrupo
                ) VALUES (
                  codigo_layout,
                  descricao,
                  layouts.db50_quantlinhas,
                  descricao,
                  layouts.db50_layouttxtgrupo
                );
            
                FOR linhas IN
            
                SELECT *
                FROM db_layoutlinha
                WHERE db51_layouttxt IN (layouts.db50_codigo)
            
                LOOP
            
                  SELECT nextval('db_layoutlinha_db51_codigo_seq')
                  INTO codigo_linha;
            
                  INSERT INTO db_layoutlinha (
                    db51_codigo,
                    db51_layouttxt,
                    db51_descr,
                    db51_tipolinha,
                    db51_tamlinha,
                    db51_linhasantes,
                    db51_linhasdepois,
                    db51_obs,
                    db51_separador,
                    db51_compacta
                  ) VALUES (
                    codigo_linha,
                    codigo_layout,
                    linhas.db51_descr,
                    linhas.db51_tipolinha,
                    linhas.db51_tamlinha,
                    linhas.db51_linhasantes,
                    linhas.db51_linhasdepois,
                    linhas.db51_obs,
                    linhas.db51_separador,
                    linhas.db51_compacta
                  );
            
                  FOR campos IN
            
                  SELECT *
                  FROM db_layoutcampos
                  WHERE db52_layoutlinha IN (linhas.db51_codigo)
            
                  LOOP
            
                    SELECT nextval('db_layoutcampos_db52_codigo_seq')
                    INTO codigo_campo;
            
                    INSERT INTO db_layoutcampos (
                      db52_codigo,
                      db52_layoutlinha,
                      db52_nome,
                      db52_descr,
                      db52_layoutformat,
                      db52_posicao,
                      db52_default,
                      db52_tamanho,
                      db52_ident,
                      db52_imprimir,
                      db52_alinha,
                      db52_obs,
                      db52_quebraapos
                    ) VALUES (
                      codigo_campo,
                      codigo_linha,
                      campos.db52_nome,
                      campos.db52_descr,
                      campos.db52_layoutformat,
                      campos.db52_posicao,
                      campos.db52_default,
                      campos.db52_tamanho,
                      campos.db52_ident,
                      campos.db52_imprimir,
                      campos.db52_alinha,
                      campos.db52_obs,
                      campos.db52_quebraapos
                    );
            
                    FOR perguntas IN
            
                    SELECT *
                    FROM avaliacaoperguntaopcaolayoutcampo
                    WHERE ed313_db_layoutcampo IN (campos.db52_codigo)
            
                    LOOP
            
                      SELECT nextval('avaliacaoperguntaopcaolayoutcampo_ed313_sequencial_seq')
                      INTO codigo_pergunta;
            
                      INSERT INTO avaliacaoperguntaopcaolayoutcampo (
                        ed313_sequencial,
                        ed313_ano,
                        ed313_db_layoutcampo,
                        ed313_avaliacaoperguntaopcao,
                        ed313_layoutvalorcampo
                      ) VALUES (
                        codigo_pergunta,
                        ano,
                        codigo_campo,
                        perguntas.ed313_avaliacaoperguntaopcao,
                        perguntas.ed313_layoutvalorcampo
                      );
            
                    END LOOP;
            
                  END LOOP;
            
                END LOOP;
            
              END LOOP;
            
              RETURN codigo_layout;
            END; $$
            
            LANGUAGE PLPGSQL;
        ";

        $this->execute($sql);
    }

