        ";

        $this->execute($sql);

        $sql = "
            CREATE OR REPLACE FUNCTION atualizar_censo_cartorio()
              RETURNS BOOLEAN AS $$
            DECLARE
              cartorio RECORD;
              existe   BOOLEAN;
            BEGIN
              FOR cartorio IN
            
              SELECT *
              FROM cartorios_censo_para_atualizar
              ORDER BY id_cartorio
            
              LOOP
            
                SELECT TRUE
                INTO existe
                FROM censocartorio
                WHERE ed291_i_codigocenso = cartorio.id_cartorio;
            
                IF existe IS TRUE
                THEN
            
                  UPDATE censocartorio
                  SET
                    ed291_c_nome        = cartorio.no_cartorio_titular,
                    ed291_i_serventia   = cartorio.co_serventia :: INTEGER,
                    ed291_i_censomunic  = cartorio.co_municipio,
                    ed291_i_codigocenso = cartorio.id_cartorio
                  WHERE censocartorio.ed291_i_codigocenso = cartorio.id_cartorio;
            
                ELSE
            
                  INSERT INTO censocartorio (
                    ed291_i_codigo,
                    ed291_c_nome,
                    ed291_i_serventia,
                    ed291_i_censomunic,
                    ed291_i_codigocenso
                  ) VALUES (
                    nextval('censocartorio_ed291_i_codigo_seq'),
                    cartorio.no_cartorio_titular,
                    cartorio.co_serventia,
                    cartorio.co_municipio,
                    cartorio.id_cartorio
                  );
            
                END IF;
            
              END LOOP;
            
              RETURN TRUE;
            END; $$
            
            LANGUAGE PLPGSQL;
        ";

        $this->execute($sql);

        $sql = "
            SELECT atualizar_censo_cartorio();
        ";

        $this->execute($sql);
    }

    private function reverterLayout()
    {
        $sql = "
            DELETE FROM avaliacaoperguntaopcaolayoutcampo
            WHERE ed313_db_layoutcampo IN (
              SELECT db52_codigo
              FROM db_layoutcampos
              WHERE db52_layoutlinha IN (
                SELECT db51_codigo
                FROM db_layoutlinha
                WHERE db51_layouttxt = 303
              )
            );
            
            DELETE FROM db_layoutcampos
            WHERE db52_layoutlinha IN (
              SELECT db51_codigo
              FROM db_layoutlinha
              WHERE db51_layouttxt = 303
            );
            
            DELETE FROM db_layoutlinha
            WHERE db51_layouttxt = 303;
            
            DELETE FROM db_layouttxt
            WHERE db50_codigo = 303;
            
            DELETE FROM censoregradisc
            WHERE ed272_ano = 2018;
        ";

        $this->execute($sql);
    }

