    private function reverterTabelaCartorio()
    {
        $sql = "
            DROP TABLE IF EXISTS cartorios_censo_para_atualizar;
            DROP FUNCTION IF EXISTS atualizar_censo_cartorio();
        ";

        $this->execute($sql);
    }

    private function reverterMenu()
    {
        $sql = "
            UPDATE db_itensmenu
